INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-21a-z0-q0','nism-21a-z0','What is the minimum statutory ticket size mandated by SEBI for an individual investor to open a Portfolio Management Services (PMS) account in India?','["₹10 Lakhs","₹25 Lakhs","₹50 Lakhs","₹1 Crore"]',2,'SEBI revised the minimum investment threshold for PMS clients to ₹50 Lakhs to ensure that only qualified high-net-worth investors participate in PMS offerings.',0) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-21a-z0-q1','nism-21a-z0','In PMS performance fee calculations, what is the significance of the "High-Water Mark" principle?','["It guarantees a minimum annual return to the investor","The Portfolio Manager cannot charge a performance incentive fee unless previous portfolio losses have been fully recouped","It caps the maximum fee a manager can earn in bull markets","It requires client funds to be held in offshore escrow accounts"]',1,'The High-Water Mark ensures that the manager is only rewarded on new net profits; if the portfolio declines, the manager receives zero performance incentive until NAV exceeds the previous peak.',1) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-21a-z0-q2','nism-21a-z0','Under Section 115UB of the Income Tax Act, which categories of Alternative Investment Funds (AIF) are granted statutory tax pass-through status?','["Category III AIFs only","Category I and Category II AIFs","All AIF categories including Category III","None; all AIFs are taxed at maximum marginal rate"]',1,'Under Section 115UB of the Income Tax Act, Category I and Category II AIFs have complete tax pass-through status (taxed in investor hands). Category III AIFs are taxed at fund level.',2) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-21a-z0-q3','nism-21a-z0','Under SEBI rules, can a Discretionary Portfolio Manager borrow funds or leverage the client''s portfolio to enhance equity returns?','["Yes, up to 2x leverage is permitted","Yes, provided the client signs a risk disclosure","No, SEBI PMS Regulations strictly prohibit portfolio managers from borrowing on behalf of the client","Only for buying index futures contracts"]',2,'Under SEBI (Portfolio Managers) Regulations, portfolio managers are strictly forbidden from leveraging the portfolio or borrowing funds on behalf of clients.',3) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-21a-z0-q4','nism-21a-z0','Which performance attribution metric evaluates the excess return generated by active security selection vs benchmark sector allocation?','["Brinson-Fachler Attribution Model","Sharpe Ratio single index","Treynor Measure beta coefficient","Modigliani-Modigliani (M2) risk-adjusted score"]',0,'The Brinson-Fachler framework separates excess portfolio returns into asset allocation effect, selection effect (stock-picking alpha), and interaction effect.',4) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
